INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, test_String) SELECT @e, 0, 10, 0, 0, 'My winds are still gathering, friend. Come back in %tqt.', 'AzimarLines:wait' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, test_String) SELECT @e, 0, 8, 0, 0, 'Well met, %s. The bright winds bring you to me.', 'AzimarLines:greet' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 22, 0, 1, 'AzimarBlessingWait' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, test_String) SELECT @e, 2, 18, 1.2, 0, '%n spreads his shimmering wings. "Be blessed, traveler. The bright winds go with you."', 'AzimarLines:open' FROM DUAL WHERE @e IS NOT NULL;
