INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, test_String) SELECT @e, 63, 8, 1.0, 0, 'Go gently, %s. The winds are with you.', 'AzimarLines:bless' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, test_String) SELECT @e, 0, 8, 0, 0, 'The winds are kind today.', 'AzimarLines:idle' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Well, hello, %s. A new face on my breeze, and such a welcome one. I am Azimar.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s, is it? The winds whispered someone charming was coming. They undersold you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'A newcomer! Come closer, %s. I only ruffle feathers by invitation.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Welcome, %s. First time with a Zefir? Relax. I am very gentle.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Oh my, %s. I do love a fresh face. Let me show you a good time. With buffs.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'Hello there, %s. I am Azimar, and you have just made my whole afternoon.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, '%s! I do not know you yet, but I would very much like to. Spiritually, of course.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Step into my breeze, %s. Everyone leaves glowing. It is sort of my thing.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Back again, %s? I knew you could not stay away. They never can.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s! I was just thinking about you. Nothing improper. Mostly.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'There you are, %s. Ready for another round? I never tire.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Ah, %s, my favourite regular. Shall we pick up where we left off?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Welcome back, %s. You bring out the sparkle in me. Literally, look.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, '%s returns! Be still, my fluttering wings.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, '%s! Days without a visit? I was starting to think you had found another Zefir.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Look who the storm blew back. I missed you, %s. Do not tell the others.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, '%s, where have you been? Never mind. All is forgiven. Come here.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Days, %s! A Zefir has needs. Mostly attention. And a little gossip.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Your %visit visit, %s! People are going to start talking about us.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s again! That is %visit times now. I think this is officially a thing.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'The %visit visit, %s. I keep count. A gentleman always keeps count.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, '%s, your %visit time! At this point I should save you a spot on my cloud.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Fresh on the road, %s? Stay close. I will show you the ropes. Gently.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'New to all this, %s? Do not worry. I have a very soft touch.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Mind the drudges, %s. Only I get to ruffle your feathers.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'My, my, %s. Someone has been busy. Very impressive. I noticed.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Look at you, %s, all confident now. It suits you terribly well.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Halfway up the mountain, %s? Stick with me. I can take you higher.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, '%s, the seasoned wanderer. Experience is so very attractive.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'I have heard your name on far breezes, %s. Whispered, mostly. Fondly.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'A veteran of many roads. Welcome, %s. Let me put the wind back in your sails.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, '%s! A legend, here, with me. Try not to make me blush. Too late.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'The high winds bow to you, %s. I would too, but I prefer to hover close.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Few climb as high as you, %s. Allow me to admire the view. Of your legacy.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Good morning, %s. Nothing wakes me up like a visit from you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Up with the sun, %s? So am I. Wide awake, in fact.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Morning, %s. Care for a little breeze with your breakfast?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Good day, %s. The sky is wide open, and so is my schedule.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'A hot afternoon, %s. I could cool you down with a breeze. Or warm you up.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Hello, %s. The midday winds are warm. So am I.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Good evening, %s. Dusk is my favourite hour. Soft light, softer winds.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'The sun is setting, %s. How romantic. For the buffing, I mean.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Evening, %s. The sky is turning gold, like me. We match. Coincidence?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Out late, %s? The night winds keep secrets. I will keep yours. All of them.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'A midnight visit, %s? How scandalous. I approve.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Can''t sleep, %s? Neither can I. What a lovely coincidence.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, '%n spreads his shimmering wings. "Hold still now. This might tickle."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%n spreads his wings wide and winks. "Close your eyes. Or don''t. Your choice."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, '%n spreads his golden wings. "Let me get a little closer. For the magic."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, '%n spreads his wings and hums a low, sultry sky song.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, '%n spreads his wings, scattering sparkles. "Brace yourself. I am very thorough."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, '%n spreads his shimmering wings. "Fifty-nine gifts. I hope you can keep up."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'There. Was it good for you too, %s? The buffs, I mean.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'All done, %s. You are positively glowing. I have that effect on people.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Go on, %s. Think of me when the glow fades. You will.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'That should last a while, %s. Unlike my patience for your next visit.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Blessed and dazzling. Come back when you want more, %s. You will want more.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'Off you go, %s. Do not break too many hearts out there. Leave some for me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, 'Fly well, %s. I would wave, but I am too busy watching you go.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Safe winds, %s. If anyone asks where you got that glow, tell them Azimar.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Your first time, %s, and you handled it beautifully. Come back whenever.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Remember the name, %s: Azimar. You will be saying it again soon.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'That glow lasts a while, %s. When it fades, you know whose wings to find.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Patience, %s. Even I need a moment between rounds. Come back in %tqt.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'So eager! I like that. Give me %tqt to catch my breath.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Again already, %s? Flattering. Try me in %tqt.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Easy, %s. Anticipation is half the fun. %tqt more.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'The winds are restless today. Or maybe that is just me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Psst, %s. Yes, you. Looking for a good time? I have buffs.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'I could ruffle more than your feathers, you know. With magic. Strictly magic.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Hmm, hmm, hmm. Do not mind me. Just hovering here, looking magnificent.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Free blessings! Warm winds! Satisfaction guaranteed or your glow back.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, '%s, you have the look of someone who could use a little lift.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, 'My kin chase storms. I prefer to chase good company. Like yours.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Lonely winds out here. Anyone fancy a blessing? Or a chat? Or both?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Ahh, a fresh morning breeze. It goes right through my feathers.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Rise and shine, %s. Come let me put a little wind in your sails.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'The stars are out. The perfect light for a little mischief.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Up late, %s? Me too. Funny how we keep finding each other.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Happy Frostfell, %s! Come under my wing. It is the warmest spot in Dereth.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s! Cold out there. Lucky for you, I run hot.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Frostfell greetings, %s. Do you like the hat? Be honest. No, be flattering.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Snow on the ground and you on my doorstep, %s. Best gift yet.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Presents hidden all over town, and the best one is hovering right here.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Brr. Someone come and stand close. For warmth. Purely for warmth.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Spring is here, %s, and so are you. Everything is blooming today.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s! Smell the flowers? I picked them myself. Well, the wind did.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Happy Spring Festival, %s. Fresh blossoms, fresh blessings.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'The eggs are hidden, the bunnies are out, and you found me, %s. Clever.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Flowers in my crown and a spring in my wingbeat. Come say hello.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Spring air does wonders for the feathers. Want a closer look?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Welcome, %s. Do I look the part? I always dress up for a wedding.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s! The royal couple are celebrating, and so am I. Come here.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'A wedding anniversary, a top hat, and you, %s. Perfect day.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Love is in the air, %s. Mostly it is me, but still.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Weddings make me sentimental. Someone come and be blessed before I cry.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'I caught the bouquet, you know. Nobody threw it. I just took it.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Another year of Dereth, %s! Watch the sky. And me. Mostly me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s! The fireworks are out and so is my good side. Come closer.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Happy Anniversary, %s. I sparkle on special days. Today is special.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Fireworks over the towns and you at my side, %s. What a year.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Ooh, fireworks. Not as bright as me, but close.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Another year of adventurers. You only get more charming, all of you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Happy New Year, %s! Resolution one: more blessings from me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s! A new year, a fresh start, and the same dashing Zefir.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'To the new year, %s. May your packs be full and your vitae empty.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'New Year greetings, %s. I saved my first blessing of the year for you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'A toast to the new year. And to anyone who comes over here.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'New year, new wings. Same old charm. Come see.' FROM DUAL WHERE @e IS NOT NULL;
